{"source":"#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    char s[105], t[105];

    scanf("%s %s", s, t);
    int i = strlen(s) - 1;
    while(i >= 0)
    {
        if(s[i] != 'z')
        {
            s[i]++;
            break;
        }
        else s[i] = 'a';
        i--;
    }

    if(strcmp(s, t) >= 0)
    {
        char newString[] = "No such string";
        strcpy(s, newString);
    }

    printf("%s\n", s);

    return 0;
}
